def squash(s: str) -> str:
    def esc(c: str) -> str:
        if c.isdigit() or c == '\\':
            return '\\' + c
        return c

    result = []
    i = 0
    n = len(s)
    while i < n:
        c = s[i]
        j = i
        while j < n and s[j] == c:
            j += 1
        run_len = j - i
        if run_len >= 3:
            result.append(str(run_len))
            result.append(esc(c))
        else:
            for _ in range(run_len):
                result.append(esc(c))
        i = j
    return ''.join(result)
